import sqlite3,glob,os
for db in glob.glob(os.path.expanduser('~/.t3/userdata/*.db'))+glob.glob(os.path.expanduser('~/.t3/userdata/*.sqlite*')):
    try:
        c=sqlite3.connect(f'file:{db}?mode=ro',uri=True)
        tabs=[r[0] for r in c.execute("select name from sqlite_master where type='table'")]
        print(db, len(tabs), [t for t in tabs if any(k in t.lower() for k in ('thread','usage','cost','token​','session'))][:15])
    except Exception as e: print(db, e)
